package palindrome

import (
	"errors"
	"strconv"
)

// Product represents a palindromic product and its factorizations.
type Product struct {
	Value          int
	Factorizations [][2]int
}

func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	for a := fmin; a <= fmax; a++ {
		for b := a; b <= fmax; b++ {
			p := a * b
			if !isPalindrome(p) {
				continue
			}
			if p < min.Value || len(min.Factorizations) == 0 {
				min = Product{p, [][2]int{{a, b}}}
			} else if p == min.Value {
				min.Factorizations = append(min.Factorizations, [2]int{a, b})
			}
			if p > max.Value || len(max.Factorizations) == 0 {
				max = Product{p, [][2]int{{a, b}}}
			} else if p == max.Value {
				max.Factorizations = append(max.Factorizations, [2]int{a, b})
			}
		}
	}

	if len(min.Factorizations) == 0 {
		return Product{}, Product{}, errors.New("no palindromes")
	}
	return min, max, nil
}

func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
```

Wait — a subtle point about the min check: `p < min.Value || len(min.Factorizations) == 0`. Since we iterate a from fmin..fmax, b from a..fmax, the products are not in sorted order. First palindrome found: min is set. If a smaller one is found later, reset. That's fine.

But note: the zero-value Product{} has Value 0 and empty Factorizations. If the first palindrome is 0 (not in the tests), the min logic: p < 0 is false, len==0 is true → set. OK.

